    }

    /**
     * https://openjdk.java.net/jeps/395#Restrictions-on-records
     */
    @Test
    void record_allowNestedWithinClass() {
        String s = "\n" +
                "class X {\n" +
                "    record Point(int x, int y) {\n" +
                "    }\n" +
                "}\n";

