        TestJdk currentJdk = TestJdk.getCurrentHostJdk();
        if (currentJdk.getMajorVersion() < 12) {
            // JDK 12 introduced "java.lang.constant.Constable"
            assertThat(ancestors, containsInAnyOrder(
                    "java.lang.CharSequence",
                    "java.lang.Object",
