        for (int i = 0; i < differenceElements.size(); i++) {
            DifferenceElement differenceElement = differenceElements.get(i);
            if (differenceElement.isAdded()) {
                replaceEolToken(differenceElements, i, lineSeparator, differenceElement);
            }
        }
    }

    private void replaceEolToken(List<DifferenceElement> differenceElements, int index, LineSeparator lineSeparator, DifferenceElement differenceElement) {
        CsmElement element = differenceElement.getElement();
        boolean isWhitespaceToken = element instanceof CsmToken && ((CsmToken) element).isNewLine();
        if (isWhitespaceToken) {
            differenceElements.set(index, new Added(CsmElement.newline(lineSeparator)));
        }
    }

